// UpdateOrders 按 opts 收集的 SET / WHERE 组合更新行,返回实际改写行数。
// SET 白名单与 WHERE 定位条件均来自列级 @updatable;有 @pk 时自动附带
// 主键列的定位方法(类型矩阵)。@scope 不参与写面,权限由读取阶段保证。
// 零 SET 或零调用方 WHERE 条件显式拒绝(Kind=set / where),不发全表 UPDATE,
// 也不静默 no-op。
// @filter 不变量恒定 AND 进 WHERE;WithoutFilter() 可整体绕过,但不豁免
// 零 where 守卫。
//
// 参数:
//   - ctx: 更新上下文。
//   - db:  数据库连接,满足 DBTX 接口即可。
//   - opts: SET / WHERE 选项(OrderUpdate.*),跨表选项编译期不可混用。
//
// 返回值:
//   - int64: 实际改写行数;0 = 未命中(条件不匹配),不隐式特判。
//   - error: 校验或执行失败时的错误。
func UpdateOrders(ctx context.Context, db DBTX, opts ...OrderUpdateOption) (int64, error) {
	st := dynq.NewUpdateState[OrderTable]()
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(st); err != nil {
			return 0, err
		}
	}
	// 空 SET / 零 where 守卫:按调用方条件数计——@filter 叠加后最终 WHERE
	// 恒非空,不得以最终 SQL 形态代替判断。
	if err := st.Validate(); err != nil {
		return 0, err
	}
	conds := make([]sq.Sqlizer, 0, 1+len(st.Wheres()))
	// 恒定条件:@filter 服务端不变量(WithoutFilter 可绕过),与调用方条件 AND。
	if !st.FilterBypassed() {
		conds = append(conds, sq.Expr("amount_cents >= ?", 0))
	}
	conds = append(conds, st.Wheres()...)
	b := sq.Update("orders").PlaceholderFormat(sq.Dollar).Where(sq.And(conds))
	for _, a := range st.Sets() {
		b = b.Set(a.Column, sq.Expr("?"+a.Cast, a.Value))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return 0, err
	}
	tag, err := db.Exec(ctx, query, args...)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}

// UpdateOrdersReturning 按 opts 收集的 SET / WHERE 组合更新行并返回被改写的
// 整行:一条 SQL 完成 SET / WHERE / RETURNING,调用方无需更新后回查。
// 命中几行返回几行;返回行序未定义(RETURNING 无 ORDER BY),不得做顺序
// 假设;零命中返回空切片 + nil error。
// 返回行语义:行值为 SET 表达式求值与 BEFORE 行级触发器改写后的新值
// (未 SET 的列保留原值),AFTER 触发器对行的后续修改不回传。
// SET 白名单、@filter 不变量(可 WithoutFilter 绕过)与零 SET / 零 WHERE
// 守卫与 UpdateOrders 一致;@scope 不参与写面,权限由读取阶段保证。
//
// 参数:
//   - ctx: 更新上下文。
//   - db:  数据库连接,满足 DBTX 接口即可。
//   - opts: SET / WHERE 选项(OrderUpdate.*),跨表选项编译期不可混用。
//
// 返回值:
//   - []Order: 被改写的整行,按命中返回;零命中为空切片。
//   - error:    校验或执行失败时的错误。
func UpdateOrdersReturning(ctx context.Context, db DBTX, opts ...OrderUpdateOption) ([]Order, error) {
	st := dynq.NewUpdateState[OrderTable]()
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(st); err != nil {
			return nil, err
		}
	}
	// 空 SET / 零 where 守卫:按调用方条件数计——@filter 叠加后最终 WHERE
	// 恒非空,不得以最终 SQL 形态代替判断。
	if err := st.Validate(); err != nil {
		return nil, err
	}
	conds := make([]sq.Sqlizer, 0, 1+len(st.Wheres()))
	// 恒定条件:@filter 服务端不变量(WithoutFilter 可绕过),与调用方条件 AND。
	if !st.FilterBypassed() {
		conds = append(conds, sq.Expr("amount_cents >= ?", 0))
	}
	conds = append(conds, st.Wheres()...)
	b := sq.Update("orders").PlaceholderFormat(sq.Dollar).Where(sq.And(conds))
	for _, a := range st.Sets() {
		b = b.Set(a.Column, sq.Expr("?"+a.Cast, a.Value))
	}
	b = b.Suffix("RETURNING id, order_no, user_id, amount_cents, status, created_at")
	query, args, err := b.ToSql()
	if err != nil {
		return nil, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rows, pgx.RowToStructByNameLax[Order])
}

// UpdateOrdersReturningByPk 按 pk 定位更新单行并返回改写后的整行:一条 SQL
// 完成 SET / WHERE / RETURNING,调用方无需更新后回查。
// 主键作为必填定位参数内建到 WHERE(与 opts 条件 AND);动态 WHERE 不保证
// 唯一,因此定位以参数承载——opts 条件是可选收窄,不再要求至少一条 Where。
// 零命中返回 pgx.ErrNoRows。
// 返回行语义:行值为 SET 表达式求值与 BEFORE 行级触发器改写后的新值
// (未 SET 的列保留原值),AFTER 触发器对行的后续修改不回传。
// SET 白名单、@filter 不变量(可 WithoutFilter 绕过)与零 SET 守卫与
// UpdateOrders 一致;@scope 不参与写面,权限由读取阶段保证。
//
// 参数:
//   - ctx: 更新上下文。
//   - db:  数据库连接,满足 DBTX 接口即可。
//   - pk:  id 列的定位值(必填;零命中即未命中)。
//   - opts: SET / WHERE 选项(OrderUpdate.*),跨表选项编译期不可混用。
//
// 返回值:
//   - Order: 被改写的整行。
//   - error: 校验或执行失败时的错误;零命中为 pgx.ErrNoRows。
func UpdateOrdersReturningByPk(ctx context.Context, db DBTX, pk int64, opts ...OrderUpdateOption) (Order, error) {
	st := dynq.NewUpdateState[OrderTable]()
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(st); err != nil {
			return Order{}, err
		}
	}
	// 主键定位内建:计入调用方条件数(Locate 不占槽位,可与 WhereIDEq
	// 等显式收窄并存),零 where 守卫因此天然满足。
	st.Locate(sq.Expr("id = ?", pk))
	if err := st.Validate(); err != nil {
		return Order{}, err
	}
	conds := make([]sq.Sqlizer, 0, 1+len(st.Wheres()))
	// 恒定条件:@filter 服务端不变量(WithoutFilter 可绕过),与调用方条件 AND。
	if !st.FilterBypassed() {
		conds = append(conds, sq.Expr("amount_cents >= ?", 0))
	}
	conds = append(conds, st.Wheres()...)
	b := sq.Update("orders").PlaceholderFormat(sq.Dollar).Where(sq.And(conds))
	for _, a := range st.Sets() {
		b = b.Set(a.Column, sq.Expr("?"+a.Cast, a.Value))
	}
	b = b.Suffix("RETURNING id, order_no, user_id, amount_cents, status, created_at")
	query, args, err := b.ToSql()
	if err != nil {
		return Order{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return Order{}, err
	}
	return pgx.CollectOneRow(rows, pgx.RowToStructByNameLax[Order])
}

// OrdersQuerySchema 是前端契约出口:返回经 opts 减法投影后的展示字段集合,
// 前端据此渲染查询组件。@internal 字段与被 opts.SelectDisabled 移除的字段不
// 出现;其余字段保留,where / sort 禁用只收窄 ops 与 sortable。
// Schema 是(生成期元数据, opts)的确定性纯函数,同一 opts 产出字节级相同
// 结果,内容 hash 可作 ETag。
//
// 参数:
//   - opts: 运行期能力收窄选项,须与 Parse/List/Count 使用同一份 opts。
//
// 返回值:
//   - dynq.ResourceSchema: 前端渲染所需的能力描述(字段、操作符、排序、分页配置)。
func OrdersQuerySchema(opts ...dynq.QueryOption) dynq.ResourceSchema {
	cfg, err := dynq.NewQueryConfig(ordersRegistry, opts...)
	if err != nil {
		// 禁用目标不在 registry 属于编程错误。Parse/List/Count/Schema 四点同参纪律
		// 下,此处 panic 显式暴露;静默吞错会掩盖权限收窄失效。
		panic(err)
	}
	return dynq.BuildSchema(ordersRegistry, cfg)
}
